    private var pending: ((String) -> Void)?
    func request(_ completion: @escaping (String) -> Void) {
        pending = completion
    }
    func prepare(_ text: String, transform: (String) -> String) -> String {
        transform(text)
    }
    func finish(_ text: String) {
        let completion = pending
        pending = nil
        completion?(text)
    }
}
let queue = FilterQueue()
print(queue.prepare("Тёплый свет") { $0.uppercased() })
queue.request { print($0) }
queue.finish("Готово")

request сохраняет параметр в pending — без @escaping это не компилируется. prepare вызывает transform сразу и ничего не хранит, поэтому остаётся non-escaping. Вывод «ТЁПЛЫЙ СВЕТ», затем «Готово».

final class SizeQueue {
    private var pending: ((Int) -> Void)?
    func request(_ completion: @escaping (Int) -> Void) { pending = completion }
    func finish(_ size: Int) {
        let completion = pending
        pending = nil
        completion?(size)
    }
    func cancel() { pending = nil }
}
final class SizeScreen {
    private(set) var size = 0
    func start(queue: SizeQueue) {
        queue.request { [weak self] size in self?.size = size }
    }
}
let queue = SizeQueue()
let screen = SizeScreen()
screen.start(queue: queue)
print(screen.size)
queue.finish(640)
print(screen.size)
queue.finish(900)
print(screen.size)

Вывод 0, 640, 640. Переносим тот же контракт на числовой размер превью, не возвращаем будущий результат обычным return.
